contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (v)); require(v <= 1000000000000000000000000000000);
        require(address(this).balance >= v);

        uint ethBefore = address(this).balance;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.Deposit{value: v}(); if (__ESBMC_reverted()) return;

        uint ethAfter = address(this).balance;
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(ethAfter == ethBefore - v && balAfter == balBefore + v);
    }

    receive() external payable {}
}

